#!/bin/sh
# Render RosarioSIS config.inc.php from environment variables on first boot.
# config.inc.php is gitignored, so the image ships without it and we generate
# one here. If a config.inc.php is already mounted/present, we leave it alone.
set -e

CONFIG=/var/www/html/config.inc.php

if [ ! -f "$CONFIG" ]; then
	cat > "$CONFIG" <<EOF
<?php
/**
 * Generated by deploy/entrypoint.sh from environment variables.
 * Do not edit by hand in the container — change the .env file instead.
 */
\$DatabaseType = 'mysql';
\$DatabaseServer = '${DB_HOST:-db}';
\$DatabasePort = '${DB_PORT:-3306}';
\$DatabaseUsername = '${DB_USER:-rosariosis}';
\$DatabasePassword = '${DB_PASSWORD:-}';
\$DatabaseName = '${DB_NAME:-rosariosis}';
\$wkhtmltopdfPath = '';
\$DefaultSyear = '${DEFAULT_SYEAR:-2025}';
\$EthiopianCalendar = ${ETHIOPIAN_CALENDAR:-true};
\$RosarioNotifyAddress = '${ROSARIO_NOTIFY_ADDRESS:-}';
\$RosarioErrorsAddress = '${ROSARIO_ERRORS_ADDRESS:-}';
\$RosarioLocales = [ 'en_US.utf8' ];
EOF
	chown www-data:www-data "$CONFIG"
	echo "[rosario-entrypoint] wrote $CONFIG (db=${DB_HOST:-db}/${DB_NAME:-rosariosis})"
fi

exec "$@"
